// Sheet AI 3x1 đã key nền xanh (chỉ giữ mảng lớn nhất giữa mỗi ô) -> WebP base64
export const NIAN_ART = 'data:image/webp;base64,';
export const nianPos = (i: number) => ({
  backgroundImage: `url(${NIAN_ART})`,
  backgroundSize: '300% 100%',
  backgroundPosition: `${(i % 3) * (100 / Math.max(1, 3 - 1))}% ${(Math.floor(i / 3)) * (100 / Math.max(1, 1 - 1))}%`,
});
